with required_tables(t) as (values ('action_issue_events'), ('action_issue_state'), ('agency_attention_setting_events'), ('agency_attention_settings'), ('agency_notification_settings'), ('agency_work_hour_policies'), ('authorization_amendment_impact_acks'), ('authorization_amendment_impacts'), ('caregiver_background_check_events'), ('caregiver_background_checks'), ('caregiver_compliance_holds'), ('caregiver_hour_limits'), ('caregiver_onboarding_items'), ('client_document_requirements'), ('client_document_types'), ('client_document_versions'), ('client_documents'), ('client_preparation'), ('client_service_holds'), ('issue_notifications'), ('onboarding_requirements'), ('organization_appearance'), ('report_export_events'), ('report_exports'), ('shift_pickup_requests'), ('shift_reconciliations'), ('user_appearance'), ('visit_authorization_reviews') union all select t from (values ('agency_open_shift_settings'), ('agency_sms_usage'), ('caregiver_coverage_cities'), ('caregiver_sms_consent'), ('caregiver_sms_consent_events'), ('notification_jobs'), ('office_notification_contacts'), ('shift_coverage_rounds'), ('platform_sms_controls')) n(t) where exists (select 1 from ogevia_meta.schema_migrations where version = '0086')),
required_functions(f) as (values ('acknowledge_authorization_amendment_impact'), ('amend_client_authorization'), ('approve_visit_for_billing'), ('assign_shift_caregiver'), ('change_shift_series_from'), ('complete_report_export'), ('confirm_service_visit'), ('confirm_shift_pickup'), ('create_caregiver'), ('create_shift'), ('create_shift_series'), ('decline_shift_pickup'), ('ensure_client_document'), ('extend_shift_series'), ('fail_report_export'), ('find_possible_duplicate_clients'), ('get_action_issue_history'), ('get_agency_performance'), ('get_appearance'), ('get_attention_counts'), ('get_attention_overview'), ('get_attention_settings'), ('get_attention_summary'), ('get_background_check_history'), ('get_caregiver_compliance'), ('get_client_document_upload_replay'), ('get_client_issue_history'), ('get_client_readiness'), ('get_compliance_attention'), ('get_compliance_summary'), ('get_active_visit_balance'), ('get_monthly_chain_report'), ('list_caregiver_hours_balances'), ('get_notification_settings'), ('get_onboarding'), ('get_utilisation_overview'), ('get_visit_authorization_review'), ('get_visit_review'), ('get_work_hour_policy'), ('list_action_issues'), ('list_audit_report'), ('list_authorization_amendment_impacts'), ('list_authorizations_missing_rate'), ('list_billing_review_visits'), ('list_caregiver_load'), ('list_caregivers'), ('list_client_audit'), ('list_client_document_types'), ('list_client_documents'), ('list_compliance_holds'), ('list_hour_limits'), ('list_monthly_service_summary'), ('list_my_notifications'), ('list_onboarding_overview'), ('list_onboarding_requirements'), ('list_open_shifts'), ('list_report_exports'), ('list_shift_pickup_requests'), ('list_shift_series'), ('list_shifts'), ('list_shifts_to_reconcile'), ('mark_notifications_read'), ('open_client_document_version'), ('open_client_service_hold'), ('pickup_open_shift'), ('preview_shift_series'), ('reconcile_ended_shift'), ('record_onboarding_item'), ('register_client_document_version'), ('release_client_service_hold'), ('request_report_export'), ('reschedule_shift'), ('resolve_visit_authorization_review'), ('review_client_document_version'), ('run_compliance_sweep'), ('save_client_document_type'), ('schedule_makeup_shift'), ('set_attention_settings'), ('set_background_check_status'), ('set_caregiver_hire_date'), ('set_caregiver_status'), ('set_client_document_requirement'), ('set_client_preparation'), ('set_hour_limit'), ('set_my_appearance'), ('set_notification_settings'), ('set_onboarding_requirement'), ('set_organization_appearance'), ('start_onboarding'), ('system_compliance_orgs'), ('system_compliance_sweep_org'), ('verify_background_check'), ('withdraw_my_shift_pickup') union all select f from (values ('post_shift_for_coverage'), ('unpost_shift'), ('set_shift_service_city'), ('list_open_shift_board'), ('get_open_shift'), ('request_open_shift'), ('withdraw_open_shift_request'), ('list_my_open_shift_requests'), ('list_coverage_queue'), ('list_coverage_requests'), ('confirm_coverage_request'), ('get_shift_coverage_status'), ('get_open_shift_settings'), ('update_open_shift_settings'), ('list_office_contacts'), ('upsert_office_contact'), ('list_caregiver_coverage_cities'), ('set_caregiver_coverage_cities'), ('set_my_sms_consent'), ('get_my_sms_consent'), ('system_sms_claim'), ('system_sms_record'), ('system_sms_receipt'), ('system_sms_stop'), ('system_coverage_sweep'), ('system_sms_reconcile'), ('get_open_shift_report'), ('list_coverage_alerts'), ('list_open_shift_audit'), ('requeue_notification')) n(f) where exists (select 1 from ogevia_meta.schema_migrations where version = '0086'))
select 'release_table_' || t as check_name,
       to_regclass('ogevia.' || t) is not null as ok,
       null::text as detail
from required_tables
union all
select 'release_function_' || f,
       exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'ogevia_api' and p.proname = f),
       null
from required_functions
union all
select 'release_function_executable_' || f,
       not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                    where n.nspname = 'ogevia_api' and p.proname = f and not has_function_privilege('ogevia_app', p.oid, 'execute')),
       null
from required_functions;
